# DK MAF.  Mariager - Fårup
with detail = 2 {
    let mf = path("d2.dk.maf");

    with railway = :first :museum {
        with link = "point.dk.Mariager" {
            statdot(mf[:mar]);
            slabel(:top, mf[:mar] + (0dt, -0.8dt), "Mariager");
        }

        with link = "line.dk.MAF" {
            track(mf[:mar, :han]);
            line_label(:left:nw, mf[:mar + 7.5km] << 0.5mt, "MAF");
        }

        with link = "point.dk.Handest" {
            statdot(mf[:han]);
            slabel(:top, mf[:han] + (-2dt, -0.8dt), "Handest");
        }
    }

    with railway = :first :pax :closed {
        with link = "line.dk.MAF" {
            track(
                    mf[:han, :far.xm - 1md]
                ..  mf[:far.ym, :far.ym + 0.1dl] << 0.5md >> 0.5mt
            );
        }
    }
}


# DK MBH.  Maribo - Bandholm
with detail = 2 {
    let mb = path("d2.dk.mbh");

    with railway = :first :museum {
        with link = "line.dk.MBH" {
            track(mb[:mar.yb, :mar.yb + 4km]);
            line_label(:right:w, mb[:mar.yb + 4km], "MBH");
            track(mb[:mar.yb + 4km, :ban]);
        }

        with link = "point.dk.Bandholm" {
            statdot(mb[:ban]);
            slabel(:top, mb[:ban] + (0dt, -0.7dt), "Bandholm");
        }
    }
}


# DK MFS.  Middelfart - Strib
with detail = 2 {
    let ms = path("d2.dk.mfs");

    with railway = :first :pax :removed {
        with link = "line.dk.MFS" {
            track(ms[:mis, :mig.ym]);
        }

        with link = "point.dk.Middelfart-gamle" {
            track(ms[:mig.ym, :mig.yo]);
            statdot(ms[:mig]);
        }

        with link = "line.dk.MFS" {
            track(ms[:mig.yo, :mig.yo + 2.9km]);
            line_label(:right:w, ms[:mig.yo + 2.9km], "MFS");
            track(ms[:mig.yo + 2.9km, :str]);
        }

        with link = "point.dk.Strib" {
            statdot(ms[:str]);
            slabel(:top, ms[:str] + (0.5dt, -0.5dt), "Strib");
        }
    }
}


